/* ===================== BÀI 3 · Tạo project và nạp chương trình ===================== */
/* Bài 3 · Tạo project và nạp chương trình (AMTS-EMB-001-M01-L03, MC51-003) — sinh bởi tools/author/mcu8051/l03.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8051 và bài tập chấm tự động (đề, code mẫu, bộ thử). Lời giải không nằm ở đây. */
const PR3=[{"label":"Ví dụ: Chương trình mẫu để nạp vào chip","code":"        ORG     0000H\n        MOV     P1,#55H                 ; LED P1.1, P1.3, P1.5, P1.7 sáng\n        SJMP    $\n        END\n","note":"Chương trình 5 byte này là mẫu đã kiểm chứng để nạp thử lần đầu. Phần Mã máy: 75 90 55 ở 0000H, 80 FE ở 0003H, đúng dữ liệu của dòng :0500000075905580FE23. Chạy xong: 55H = 0101 0101B nên LED P1.1, P1.3, P1.5, P1.7 sáng.","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: Hai đoạn ORG thành hai bản ghi HEX","code":"        ORG     0000H                   ; vectơ reset\n        LJMP    MAIN\n        ORG     0030H                   ; đoạn mã thứ hai\nMAIN:   MOV     P1,#0AAH                ; LED P1.0, P1.2, P1.4, P1.6 sáng\n        SJMP    $\n        END\n","note":"Hai đoạn mã: 02 00 30 ở 0000H và 75 90 AA 80 FE ở 0030H. File HEX có hai bản ghi dữ liệu tương ứng (:03000000020030CB và :050030007590AA80FE9E); vùng giữa không có trong file.","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: Tính byte kiểm tra của một dòng HEX","code":"        ORG     0000H\n; bản ghi HEX của ví dụ 1 (chưa có byte kiểm tra)\n        MOV     30H,#05H                ; LL: 5 byte dữ liệu\n        MOV     31H,#00H                ; địa chỉ, byte cao\n        MOV     32H,#00H                ; địa chỉ, byte thấp\n        MOV     33H,#00H                ; loại 00: dữ liệu\n        MOV     34H,#75H                ; 5 byte mã máy\n        MOV     35H,#90H\n        MOV     36H,#55H\n        MOV     37H,#80H\n        MOV     38H,#0FEH\n        MOV     R0,#30H                 ; con trỏ tới byte đầu\n        MOV     R7,#9                   ; 9 byte cần cộng\n        CLR     A\nCONG:   ADD     A,@R0                   ; cộng dồn, bỏ phần tràn\n        INC     R0\n        DJNZ    R7,CONG\n        CPL     A                       ; số bù 2: đảo bit rồi cộng 1\n        INC     A\n        MOV     39H,A                   ; byte kiểm tra\n        SJMP    $\n        END\n","note":"Chín byte của dòng HEX ví dụ 1 được chép vào 30H–38H, vòng CONG cộng dồn vào A (tràn bị bỏ). Đoán trước: sau vòng lặp A bằng bao nhiêu? (DDH, 8 bit thấp của 2DDH.) CPL A rồi INC A cho 23H, ghi vào 39H, đúng byte cuối của dòng HEX.","dev":{"led":true},"fosc":12000000},{"label":"Lỗi: Build báo nhãn chưa định nghĩa","code":"        ORG     0000H\n        MOV     R7,#5\nLAP:    CPL     P1.0                    ; đảo LED P1.0\n        DJNZ    R7,LOP                  ; gõ nhầm tên nhãn\n        SJMP    $\n        END\n","note":"Bấm Chạy: trình dịch báo lỗi ở dòng 4 vì nhãn LOP chưa được định nghĩa (nhãn thật là LAP). Khi build lỗi, không có file HEX mới; sửa LOP thành LAP rồi chạy lại.","dev":{"led":true},"fosc":12000000},{"label":"Lỗi: Lệnh SUB không có trên 8051","code":"        ORG     0000H\n        MOV     A,#10\n        SUB     A,#3                    ; nhầm: 8051 không có lệnh SUB\n        MOV     P1,A\n        SJMP    $\n        END\n","note":"Trình dịch báo lỗi ở dòng 3: 8051 không có lệnh SUB, phép trừ dùng SUBB (trừ cả cờ mượn CY). Đọc kỹ dòng lỗi trong Build Output trước khi nạp: số dòng và tên lệnh bị báo.","dev":{"led":true},"fosc":12000000},{"label":"Bẫy: Trễ tính cho 12 MHz, bo dùng 11,0592 MHz","code":"        ORG     0000H\n; trễ “1 ms” viết cho thạch anh 12 MHz\n        MOV     R6,#2\nNGOAI:  MOV     R7,#249\nTRONG:  DJNZ    R7,TRONG                ; 249 × 2 chu kỳ máy\n        DJNZ    R6,NGOAI\n        CPL     P1.0                    ; đổi trạng thái LED sau trễ\n        SJMP    $\n        END\n","note":"Ví dụ này chạy với thạch anh 11,0592 MHz. Vòng trễ tốn 1 + 2 × (1 + 249 × 2 + 2) + 1 = 1 004 chu kỳ máy trước khi đổi LED: 1 004 µs ở 12 MHz nhưng khoảng 1 089,41 µs ở 11,0592 MHz. Mã máy hai trường hợp giống hệt; chỉ thời gian khác.","dev":{"led":true},"fosc":11059200}];
const sim3=makeSim51(document.getElementById("m51-l3"),{id:"s3",presets:PR3,ram:256});
makeEx51(document.getElementById("ex-l3"),"l3",[{"t":"Byte kiểm tra của dòng HEX","d":"<p>Tám ô <code>30H<\/code>–<code>37H<\/code> chứa một bản ghi Intel HEX chưa có byte kiểm tra: <code>30H<\/code> = LL (luôn là 04H), <code>31H<\/code>, <code>32H<\/code> = địa chỉ (byte cao, byte thấp), <code>33H<\/code> = loại bản ghi, <code>34H<\/code>–<code>37H<\/code> = 4 byte dữ liệu. Viết chương trình tính byte kiểm tra (checksum) và ghi vào <code>38H<\/code>: cộng 8 byte, chỉ giữ 8 bit thấp của tổng, rồi lấy số bù 2. Các ô <code>30H<\/code>–<code>37H<\/code> giữ nguyên. Kết thúc bằng <code>SJMP $<\/code>.<\/p><p>Ví dụ: <code>04 00 00 00 75 90 55 80<\/code> → tổng = 1DEH, 8 bit thấp = DEH → <code>38H = 22H<\/code>.<\/p>","start":"        ORG     0000H\n; 30H..37H: LL, địa chỉ cao, địa chỉ thấp, loại, 4 byte\n; Ghi byte kiểm tra vào 38H\n; Viết code ở đây\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":4,"0x31":0,"0x32":0,"0x33":0,"0x34":117,"0x35":144,"0x36":85,"0x37":128,"0x38":238}},"expect":{"iram":{"0x30":4,"0x31":0,"0x32":0,"0x33":0,"0x34":117,"0x35":144,"0x36":85,"0x37":128,"0x38":34}}},{"setup":{"iram":{"0x30":4,"0x31":0,"0x32":48,"0x33":0,"0x34":117,"0x35":144,"0x36":170,"0x37":128,"0x38":238}},"expect":{"iram":{"0x30":4,"0x31":0,"0x32":48,"0x33":0,"0x34":117,"0x35":144,"0x36":170,"0x37":128,"0x38":157}}},{"setup":{"iram":{"0x30":4,"0x31":0,"0x32":0,"0x33":0,"0x34":0,"0x35":0,"0x36":0,"0x37":0,"0x38":238}},"expect":{"iram":{"0x30":4,"0x31":0,"0x32":0,"0x33":0,"0x34":0,"0x35":0,"0x36":0,"0x37":0,"0x38":252}}},{"setup":{"iram":{"0x30":4,"0x31":31,"0x32":252,"0x33":0,"0x34":255,"0x35":255,"0x36":255,"0x37":255,"0x38":238}},"expect":{"iram":{"0x30":4,"0x31":31,"0x32":252,"0x33":0,"0x34":255,"0x35":255,"0x36":255,"0x37":255,"0x38":229}}},{"setup":{"iram":{"0x30":4,"0x31":1,"0x32":0,"0x33":0,"0x34":124,"0x35":0,"0x36":0,"0x37":127,"0x38":238}},"expect":{"iram":{"0x30":4,"0x31":1,"0x32":0,"0x33":0,"0x34":124,"0x35":0,"0x36":0,"0x37":127,"0x38":0}}},{"setup":{"iram":{"0x30":4,"0x31":0,"0x32":0,"0x33":0,"0x34":18,"0x35":52,"0x36":86,"0x37":120,"0x38":238}},"expect":{"iram":{"0x30":4,"0x31":0,"0x32":0,"0x33":0,"0x34":18,"0x35":52,"0x36":86,"0x37":120,"0x38":232}}}]},"hints":["Cộng lần lượt bằng ADD A,ô: phần tràn ra cờ CY bị bỏ, đúng như định nghĩa (chỉ giữ 8 bit thấp).","Số bù 2 của x là (100H − x) lấy 8 bit thấp: đảo mọi bit (CPL A) rồi cộng 1 (INC A).","Cộng đủ 8 byte trước, lấy số bù 2 một lần ở cuối. Thử với tổng bằng 0: số bù 2 của 0 là bao nhiêu?"],"why":"Byte kiểm tra làm cho tổng mọi byte của dòng (kể cả nó) chia hết cho 100H. Bộ thử 5 có tổng đúng bằng 100H nên byte kiểm tra là 00H: lời giải chỉ đảo bit sẽ ra FFH."},{"t":"Kiểm tra một dòng HEX","d":"<p>Một dòng Intel HEX đã đổi sang byte nằm từ ô <code>40H<\/code>: <code>40H<\/code> = LL (0–16), tiếp theo 2 byte địa chỉ, 1 byte loại, LL byte dữ liệu và 1 byte kiểm tra — tổng cộng LL + 5 byte. Viết chương trình kiểm dòng đó như phần mềm nạp làm trước khi ghi Flash: <code>30H = 01H<\/code> nếu tổng mọi byte của dòng (kể cả byte kiểm tra), lấy 8 bit thấp, bằng <code>00H<\/code>; ngược lại <code>30H = 00H<\/code>. Các ô từ <code>40H<\/code> giữ nguyên. Kết thúc bằng <code>SJMP $<\/code>.<\/p><p>Ví dụ: dòng <code>:0500000075905580FE23<\/code> → byte <code>05 00 00 00 75 90 55 80 FE 23<\/code> ở <code>40H<\/code>–<code>49H<\/code> → tổng = 300H → <code>30H = 01H<\/code>.<\/p>","start":"        ORG     0000H\n; Dòng HEX ở 40H: LL, địa chỉ (2 byte), loại,\n; LL byte dữ liệu, byte kiểm tra\n; 30H = 01H nếu dòng đúng, 00H nếu sai\n        MOV     30H,#01H                ; chưa kiểm gì: luôn báo đúng\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x40":5,"0x41":0,"0x42":0,"0x43":0,"0x44":117,"0x45":144,"0x46":85,"0x47":128,"0x48":254,"0x49":35,"0x30":238}},"expect":{"iram":{"0x40":5,"0x41":0,"0x42":0,"0x43":0,"0x44":117,"0x45":144,"0x46":85,"0x47":128,"0x48":254,"0x49":35,"0x30":1}}},{"setup":{"iram":{"0x40":0,"0x41":0,"0x42":0,"0x43":1,"0x44":255,"0x30":238}},"expect":{"iram":{"0x40":0,"0x41":0,"0x42":0,"0x43":1,"0x44":255,"0x30":1}}},{"setup":{"iram":{"0x40":5,"0x41":0,"0x42":0,"0x43":0,"0x44":117,"0x45":144,"0x46":85,"0x47":128,"0x48":254,"0x49":36,"0x30":238}},"expect":{"iram":{"0x40":5,"0x41":0,"0x42":0,"0x43":0,"0x44":117,"0x45":144,"0x46":85,"0x47":128,"0x48":254,"0x49":36,"0x30":0}}},{"setup":{"iram":{"0x40":5,"0x41":0,"0x42":0,"0x43":0,"0x44":117,"0x45":145,"0x46":85,"0x47":128,"0x48":254,"0x49":35,"0x30":238}},"expect":{"iram":{"0x40":5,"0x41":0,"0x42":0,"0x43":0,"0x44":117,"0x45":145,"0x46":85,"0x47":128,"0x48":254,"0x49":35,"0x30":0}}},{"setup":{"iram":{"0x40":16,"0x41":0,"0x42":16,"0x43":0,"0x44":16,"0x45":17,"0x46":18,"0x47":19,"0x48":20,"0x49":21,"0x4A":22,"0x4B":23,"0x4C":24,"0x4D":25,"0x4E":26,"0x4F":27,"0x50":28,"0x51":29,"0x52":30,"0x53":31,"0x54":104,"0x30":238}},"expect":{"iram":{"0x40":16,"0x41":0,"0x42":16,"0x43":0,"0x44":16,"0x45":17,"0x46":18,"0x47":19,"0x48":20,"0x49":21,"0x4A":22,"0x4B":23,"0x4C":24,"0x4D":25,"0x4E":26,"0x4F":27,"0x50":28,"0x51":29,"0x52":30,"0x53":31,"0x54":104,"0x30":1}}},{"setup":{"iram":{"0x40":16,"0x41":0,"0x42":16,"0x43":0,"0x44":16,"0x45":17,"0x46":18,"0x47":19,"0x48":20,"0x49":21,"0x4A":22,"0x4B":23,"0x4C":24,"0x4D":25,"0x4E":26,"0x4F":27,"0x50":28,"0x51":29,"0x52":30,"0x53":31,"0x54":232,"0x30":238}},"expect":{"iram":{"0x40":16,"0x41":0,"0x42":16,"0x43":0,"0x44":16,"0x45":17,"0x46":18,"0x47":19,"0x48":20,"0x49":21,"0x4A":22,"0x4B":23,"0x4C":24,"0x4D":25,"0x4E":26,"0x4F":27,"0x50":28,"0x51":29,"0x52":30,"0x53":31,"0x54":232,"0x30":0}}},{"setup":{"iram":{"0x40":1,"0x41":0,"0x42":48,"0x43":0,"0x44":165,"0x45":42,"0x30":238}},"expect":{"iram":{"0x40":1,"0x41":0,"0x42":48,"0x43":0,"0x44":165,"0x45":42,"0x30":1}}},{"setup":{"iram":{"0x40":8,"0x41":0,"0x42":0,"0x43":0,"0x44":255,"0x45":255,"0x46":255,"0x47":255,"0x48":255,"0x49":255,"0x4A":255,"0x4B":255,"0x4C":0,"0x30":238}},"expect":{"iram":{"0x40":8,"0x41":0,"0x42":0,"0x43":0,"0x44":255,"0x45":255,"0x46":255,"0x47":255,"0x48":255,"0x49":255,"0x4A":255,"0x4B":255,"0x4C":0,"0x30":1}}}]},"hints":["Số byte cần cộng phụ thuộc LL: đọc LL ở 40H rồi cộng thêm 5 để có số vòng lặp.","Dùng R0 làm con trỏ (ADD A,@R0; INC R0) và R7 làm bộ đếm (DJNZ R7,…). Với LL = 0 (bản ghi kết thúc) vẫn có 5 byte.","Ghi trước giá trị “đúng” vào 30H rồi dùng một lệnh nhảy theo A để bỏ qua nhánh “sai”; lệnh MOV vào ô nhớ không làm đổi A."],"why":"Dòng đúng khi tổng mọi byte chia hết cho 100H, nên chỉ cần kiểm 8 bit thấp của tổng bằng 0. Số byte là LL + 5 chứ không cố định: bản ghi kết thúc :00000001FF (bộ thử 2) có LL = 0, dòng 16 byte có 21 byte."},{"t":"Checksum 16 byte dưới 70 chu kỳ","d":"<p>Ô <code>40H<\/code>–<code>53H<\/code> chứa một bản ghi 16 byte dữ liệu chưa có byte kiểm tra (LL = 10H, 2 byte địa chỉ, 1 byte loại, 16 byte dữ liệu: 20 byte). Code mẫu cộng 20 byte nhưng ghi sai kết quả và chạy chậm. Hãy sửa để: (1) <code>54H<\/code> = byte kiểm tra đúng của bản ghi; (2) các ô <code>40H<\/code>–<code>53H<\/code> giữ nguyên; (3) toàn chương trình chạy không quá <b>70 chu kỳ máy<\/b> (tính cả một lần <code>SJMP $<\/code>) và mã dài không quá <b>18 byte<\/b>.<\/p><p>Ở 12 MHz, 70 chu kỳ máy là 70 µs; phần mềm nạp phải tính byte kiểm tra cho hàng trăm dòng như thế.<\/p>","start":"        ORG     0000H\n; 40H..53H: dòng HEX 16 byte dữ liệu (20 byte)\n        MOV     R0,#40H\n        MOV     R7,#20\n        CLR     A\nCONG:   ADD     A,@R0\n        INC     R0\n        DJNZ    R7,CONG\n        MOV     54H,A                   ; byte kiểm tra?\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x40":16,"0x41":0,"0x42":0,"0x43":0,"0x44":0,"0x45":1,"0x46":2,"0x47":3,"0x48":4,"0x49":5,"0x4A":6,"0x4B":7,"0x4C":8,"0x4D":9,"0x4E":10,"0x4F":11,"0x50":12,"0x51":13,"0x52":14,"0x53":15,"0x54":238}},"expect":{"iram":{"0x40":16,"0x41":0,"0x42":0,"0x43":0,"0x44":0,"0x45":1,"0x46":2,"0x47":3,"0x48":4,"0x49":5,"0x4A":6,"0x4B":7,"0x4C":8,"0x4D":9,"0x4E":10,"0x4F":11,"0x50":12,"0x51":13,"0x52":14,"0x53":15,"0x54":120}}},{"setup":{"iram":{"0x40":16,"0x41":0,"0x42":16,"0x43":0,"0x44":255,"0x45":255,"0x46":255,"0x47":255,"0x48":255,"0x49":255,"0x4A":255,"0x4B":255,"0x4C":255,"0x4D":255,"0x4E":255,"0x4F":255,"0x50":255,"0x51":255,"0x52":255,"0x53":255,"0x54":238}},"expect":{"iram":{"0x40":16,"0x41":0,"0x42":16,"0x43":0,"0x44":255,"0x45":255,"0x46":255,"0x47":255,"0x48":255,"0x49":255,"0x4A":255,"0x4B":255,"0x4C":255,"0x4D":255,"0x4E":255,"0x4F":255,"0x50":255,"0x51":255,"0x52":255,"0x53":255,"0x54":240}}},{"setup":{"iram":{"0x40":16,"0x41":0,"0x42":0,"0x43":0,"0x44":0,"0x45":0,"0x46":0,"0x47":0,"0x48":0,"0x49":0,"0x4A":0,"0x4B":0,"0x4C":0,"0x4D":0,"0x4E":0,"0x4F":0,"0x50":0,"0x51":0,"0x52":0,"0x53":0,"0x54":238}},"expect":{"iram":{"0x40":16,"0x41":0,"0x42":0,"0x43":0,"0x44":0,"0x45":0,"0x46":0,"0x47":0,"0x48":0,"0x49":0,"0x4A":0,"0x4B":0,"0x4C":0,"0x4D":0,"0x4E":0,"0x4F":0,"0x50":0,"0x51":0,"0x52":0,"0x53":0,"0x54":240}}},{"setup":{"iram":{"0x40":16,"0x41":31,"0x42":240,"0x43":0,"0x44":128,"0x45":128,"0x46":128,"0x47":128,"0x48":128,"0x49":128,"0x4A":128,"0x4B":128,"0x4C":128,"0x4D":128,"0x4E":128,"0x4F":128,"0x50":128,"0x51":128,"0x52":128,"0x53":97,"0x54":238}},"expect":{"iram":{"0x40":16,"0x41":31,"0x42":240,"0x43":0,"0x44":128,"0x45":128,"0x46":128,"0x47":128,"0x48":128,"0x49":128,"0x4A":128,"0x4B":128,"0x4C":128,"0x4D":128,"0x4E":128,"0x4F":128,"0x50":128,"0x51":128,"0x52":128,"0x53":97,"0x54":0}}},{"setup":{"iram":{"0x40":16,"0x41":1,"0x42":32,"0x43":0,"0x44":117,"0x45":144,"0x46":85,"0x47":128,"0x48":254,"0x49":2,"0x4A":0,"0x4B":48,"0x4C":228,"0x4D":246,"0x4E":8,"0x4F":184,"0x50":0,"0x51":249,"0x52":128,"0x53":254,"0x54":238}},"expect":{"iram":{"0x40":16,"0x41":1,"0x42":32,"0x43":0,"0x44":117,"0x45":144,"0x46":85,"0x47":128,"0x48":254,"0x49":2,"0x4A":0,"0x4B":48,"0x4C":228,"0x4D":246,"0x4E":8,"0x4F":184,"0x50":0,"0x51":249,"0x52":128,"0x53":254,"0x54":180}}},{"setup":{"iram":{"0x40":16,"0x41":0,"0x42":0,"0x43":0,"0x44":1,"0x45":2,"0x46":4,"0x47":8,"0x48":16,"0x49":32,"0x4A":64,"0x4B":128,"0x4C":1,"0x4D":2,"0x4E":4,"0x4F":8,"0x50":16,"0x51":32,"0x52":64,"0x53":128,"0x54":238}},"expect":{"iram":{"0x40":16,"0x41":0,"0x42":0,"0x43":0,"0x44":1,"0x45":2,"0x46":4,"0x47":8,"0x48":16,"0x49":32,"0x4A":64,"0x4B":128,"0x4C":1,"0x4D":2,"0x4E":4,"0x4F":8,"0x50":16,"0x51":32,"0x52":64,"0x53":128,"0x54":242}}}],"maxCyc":70,"maxBytes":18},"hints":["Code mẫu ghi tổng chứ chưa ghi số bù 2 của tổng. Sửa lỗi đó trước (thêm hai lệnh 1 byte), rồi đo lại chu kỳ.","Mỗi vòng của code mẫu tốn 1 + 1 + 2 = 4 chu kỳ cho 1 byte; lệnh DJNZ (2 chu kỳ) là phần đắt nhất. Tổng khoảng 88 chu kỳ.","Giảm số lần DJNZ bằng cách cộng nhiều byte trong một vòng; chọn số byte mỗi vòng sao cho vừa dưới 70 chu kỳ mà mã vẫn trong giới hạn byte."],"why":"Byte kiểm tra là số bù 2 của tổng (CPL A; INC A), code mẫu quên bước này. Trải vòng lặp 2 lần: 10 vòng × 6 chu kỳ + 3 chu kỳ khởi tạo + 3 chu kỳ cuối + 2 chu kỳ SJMP $ = 68 chu kỳ, mã 17 byte. Trải 4 lần nhanh hơn (58 chu kỳ) nhưng 21 byte; không trải thì 88 chu kỳ: đây là bài cân bằng tốc độ với kích thước mã."}]);

makeQuiz("quiz3","score3",[{"q": "Một bản ghi HEX gồm các byte 03 00 30 00 02 00 30 (chưa có byte kiểm tra). Byte kiểm tra là bao nhiêu?", "o": ["9AH", "65H", "35H", "9BH"], "a": 3, "e": "Tổng 03 + 30 + 02 + 30 = 65H; số bù 2: 100H − 65H = 9BH. 9AH là chỉ đảo bit (số bù 1), quên cộng 1; 65H là chính tổng."}, {"q": "Dòng cuối của file HEX là :00000001FF. Dòng này có nghĩa gì?", "o": ["Bản ghi kết thúc file, không có byte dữ liệu", "Ghi một byte FFH vào địa chỉ 0001H", "Ghi byte 01H vào địa chỉ 0000H", "Xóa toàn bộ Flash trước khi nạp"], "a": 0, "e": "LL = 00 (không có dữ liệu), địa chỉ 0000, loại 01 = kết thúc file, FF là byte kiểm tra (100H − 01H). Không có byte nào được ghi vào Flash từ dòng này."}, {"q": "Build thành công nhưng phần mềm nạp không thấy file HEX mới nào trong thư mục project. Nguyên nhân thường gặp nhất là gì?", "o": ["Ô Xtal đặt 11.0592 thay vì 12.0", "Chưa chép STARTUP.A51 vào project", "Chưa bật Create HEX File trong Options for Target → Output", "Chân EA của chip đang nối GND"], "a": 2, "e": "Không bật Create HEX File thì trình liên kết vẫn tạo file tuyệt đối nhưng không đổi sang HEX. Xtal chỉ ảnh hưởng thời gian khi mô phỏng; EA là chuyện phần cứng, không liên quan tới file trên máy tính."}, {"q": "Trong lúc nạp ISP cho AT89S52, chân RST phải ở mức nào?", "o": ["Mức 1 suốt quá trình nạp", "Mức 0 suốt quá trình nạp", "Nhảy 0–1 theo xung SCK", "Để hở, bộ nạp không dùng chân này"], "a": 0, "e": "Bộ nạp giữ RST = 1 để CPU dừng và chip vào chế độ nạp nối tiếp; khi RST về 0, chip ra khỏi trạng thái reset và chạy chương trình mới từ 0000H."}, {"q": "Project đặt Xtal = 12.0 nhưng bo dùng thạch anh 11,0592 MHz. Nạp chương trình hợp ngữ vào chip thì điều gì xảy ra?", "o": ["Chip không chạy vì tần số trong file HEX sai", "Mã máy không đổi; chip chạy theo 11,0592 MHz nên vòng trễ dài hơn tính toán", "Phần mềm nạp báo lỗi verify", "Mã máy được dịch lại cho 12 MHz nên thời gian đúng"], "a": 1, "e": "File HEX chỉ chứa byte mã máy, không chứa tần số. Ô Xtal dùng cho trình mô phỏng của µVision; chip thật chạy theo thạch anh trên bo, nên trễ 1 004 chu kỳ thành khoảng 1 089 µs."}]);

